async function finance(){
 if(!isAdmin())return go('dashboard');
 const period=[3,6,12].includes(state.financePeriod)?state.financePeriod:6;
 const [d,report,dash]=await Promise.all([load('finance'),api('reports/financial?period='+period),api('dashboard')]);
 state.data.financialReport=report;
 const totals=dash.finance||{},received=Number(totals.received)||0,spent=Number(totals.spent)||0,rec=Number(totals.receivable)||0,pay=Number(totals.payable)||0;
 const periodSelect=`<label class="finance-period">PERÍODO <select id="finance-period" aria-label="Período do gráfico financeiro">${[3,6,12].map(n=>`<option value="${n}" ${n===period?'selected':''}>${n} meses</option>`).join('')}</select></label>`;
 const cashPanel=panel('Evolução do fluxo de caixa',financialChart(report.months,period),periodSelect);
 const costPanel=panel('Despesas por categoria',expenseDonutChart(report.expense_categories));
 const reportSummary=`<div class="report-values"><div><span>Margem bruta estimada · pedidos confirmados</span><strong>${money(report.margin_cents)}</strong></div><div><span>Estoque valorizado a custo de aquisição</span><strong>${money(report.stock_value_cents)}</strong></div><div><span>Resultado realizado do período</span><strong class="${Number(report.period_balance_cents)>=0?'positive':'negative'}">${new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format((Number(report.period_balance_cents)||0)/100)}</strong></div><p>O saldo realizado considera pagamentos recebidos e despesas pagas no período. A margem bruta é uma estimativa e não representa lucro líquido.</p></div>`;
 $('#workspace').innerHTML=header('CENTRO FINANCEIRO','Financeiro','Visualize receitas, despesas e fluxo de caixa com base nos lançamentos registrados.',`<button class="btn ghost" data-action="finance-export">Exportar lançamentos ↓</button><button class="btn primary" data-action="finance-new">+ Novo lançamento</button>`)+
 `<div class="mini-stats finance-stats">${stat('Entradas recebidas',money(received),'Lançamentos pagos · histórico','↗','strong')}${stat('Despesas pagas',money(spent),'Saídas realizadas · histórico','↘')}${stat('A receber',money(rec),'Receitas em aberto','◷')}${stat('A pagar',money(pay),'Despesas em aberto','!')}</div><div class="finance-report-grid">${cashPanel}${costPanel}</div><div class="finance-report-grid finance-insights-grid">${panel('Visão de resultado e capital',reportSummary)}${panel('Indicadores para acompanhar',`<div class="finance-guide"><div><span class="finance-insight-pill">◉ RECEITA REALIZADA</span><p>Somente valores efetivamente marcados como pagos entram no fluxo.</p></div><div><span class="finance-insight-pill">◌ CONTAS PENDENTES</span><p>Valores a receber e a pagar ficam separados do caixa realizado.</p></div><div><span class="finance-insight-pill">▣ ESTOQUE</span><p>O custo do estoque não é uma despesa paga automaticamente.</p></div></div>`)}</div>`+
 panel('Livro financeiro',d.items.length?rows(['LANÇAMENTO','TIPO','CATEGORIA','VENCIMENTO','VALOR','STATUS',''],d.items.map(f=>`<tr><td><strong>${esc(f.title)}</strong><small class="cell-secondary">${esc(f.method)}</small></td><td>${badge(f.type,f.type==='receita'?'green':'red')}</td><td>${esc(f.category)}</td><td>${dateBR(f.due_date)}</td><td><strong>${money(f.amount_cents)}</strong></td><td>${badge(f.status,f.status==='pago'?'green':'amber')}</td><td>${f.status==='pendente'?`<button class="table-btn" data-action="finance-pay" data-id="${f.id}">Marcar pago</button>`:''}</td></tr>`)):empty('Sem lançamentos financeiros','Registre uma receita ou despesa. Vendas confirmadas criam contas a receber automaticamente.'));
 const control=$('#finance-period');if(control)control.onchange=()=>{state.financePeriod=Number(control.value);finance().catch(err=>toast(err.message,'error'))};
}
function exportFinancialCSV(){
 if(!isAdmin())return;
 const rows=state.data.finance?.items||[];
 if(!rows.length)return toast('Nenhum lançamento disponível para exportação.','error');
 const safe=v=>{let text=String(v??'');if(/^[\s]*[=+@-]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"'};
 const data=[['Título','Tipo','Categoria','Vencimento','Valor (R$)','Situação','Forma de pagamento'],...rows.map(x=>[x.title,x.type,x.category,x.due_date||'',(Number(x.amount_cents||0)/100).toFixed(2).replace('.',','),x.status,x.method])];
 const blob=new Blob(['\ufeff'+data.map(line=>line.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});
 const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='macumbiinha-financeiro-'+new Date().toISOString().slice(0,10)+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('CSV dos lançamentos carregados exportado.');
}
