function modal(title,body,opts={}){const layer=$('#modal-layer');layer.innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><span class="eyebrow">MACUMBIINHA / GESTÃO</span><h2 id="modal-title">${esc(title)}</h2></div><button class="modal-close" data-action="modal-close" aria-label="Fechar">×</button></div><div class="modal-content">${body}</div></div></div>`;layer.classList.add('open');$('input,select,button',$('.modal'))?.focus();layer.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()});document.addEventListener('keydown',escapeModal);return layer}
function escapeModal(e){if(e.key==='Escape')closeModal()}
function closeModal(){const l=$('#modal-layer');if(l){l.classList.remove('open');l.innerHTML=''}document.removeEventListener('keydown',escapeModal)}
const input=(label,name,value='',type='text',required=false,extra='')=>`<label class="field"><span>${label}${required?' *':''}</span><input name="${name}" type="${type}" value="${esc(value??'')}" ${required?'required':''} ${extra}></label>`;
const textarea=(label,name,value='')=>`<label class="field"><span>${label}</span><textarea name="${name}" rows="3">${esc(value||'')}</textarea></label>`;
const select=(label,name,options,value='',required=false)=>`<label class="field"><span>${label}${required?' *':''}</span><select name="${name}" ${required?'required':''}>${options.map(([key,title])=>`<option value="${esc(key)}" ${String(key)===String(value)?'selected':''}>${esc(title)}</option>`).join('')}</select></label>`;
const form=(fields,label='Salvar',id='entry-form')=>`<form id="${id}" class="form-layout">${fields}<div class="form-foot"><button type="button" data-action="modal-close" class="btn ghost">Cancelar</button><button type="submit" class="btn primary">${label}</button></div></form>`;
async function submitForm(id,onSubmit){const el=$('#'+id);el.addEventListener('submit',async e=>{e.preventDefault();const submit=$('[type=submit]',el);submit.disabled=true;try{const data=Object.fromEntries(new FormData(el));await onSubmit(data);closeModal();toast('Alterações salvas com sucesso.');await renderSection();pollAlerts(true)}catch(err){toast(err.message,'error');submit.disabled=false}})}
