async function openOrder(){
 if(!state.data.contacts)await load('contacts');if(!state.data.products)await load('products');const list=state.data.products.items.filter(x=>x.active);
 if(!list.length)return toast('Cadastre produtos antes de criar pedidos.','error');
 const options=list.map(p=>[p.id,p.name+' · '+p.sku]);
 modal('Novo pedido',`<form id="order-form" class="form-layout"><div class="form-grid">${select('Cliente','contact_id',contactOptions())}${select('Tipo de venda','segment',[['varejo','Varejo'],['atacado','Atacado']],'varejo',true)}${select('Origem','origin',[['manual','Manual'],['site','Site'],['whatsapp','WhatsApp']],'manual')}</div><div class="form-divider"><strong>Produtos do pedido</strong><button type="button" class="table-btn" id="add-line">+ Adicionar item</button></div><div id="order-lines"></div><div class="form-grid">${input('Frete (R$)','shipping_real','0,00','text',false,'inputmode="decimal"')}${input('Desconto (R$)','discount_real','0,00','text',false,'inputmode="decimal"')}</div><div class="order-total"><span>Total estimado</span><strong id="order-total">R$ 0,00</strong></div>${textarea('Observações','notes')}<p class="form-hint">O pedido será criado como novo e só descontará estoque após sua confirmação.</p><div class="form-foot"><button type="button" class="btn ghost" data-action="modal-close">Cancelar</button><button type="submit" class="btn primary">Criar pedido</button></div></form>`);
 const addLine=()=>{const div=document.createElement('div');div.className='order-line';div.innerHTML=`${select('Produto','product_id',options,options[0][0])}${input('Quantidade','quantity',1,'number',true,'min="1" max="9999"')}<button type="button" class="line-remove" aria-label="Remover item">×</button><span class="line-price"></span>`;$('#order-lines').append(div);$('.line-remove',div).onclick=()=>{div.remove();recalc()};$$('input,select',div).forEach(el=>el.addEventListener('input',recalc));recalc()};
 const recalc=()=>{const segment=$('[name=segment]','#order-form').value;let total=0;$$('.order-line').forEach(row=>{const p=list.find(x=>x.id===$('[name=product_id]',row)?.value),q=Math.max(0,Number($('[name=quantity]',row)?.value)||0),price=segment==='atacado'?p?.wholesale_cents:p?.retail_cents;const sum=q*(price||0);total+=sum;$('.line-price',row).textContent=money(sum)});total+=moneyCents($('[name=shipping_real]','#order-form').value)-moneyCents($('[name=discount_real]','#order-form').value);$('#order-total').textContent=money(Math.max(0,total))};
 $('#add-line').onclick=addLine;$$('[name=segment],[name=shipping_real],[name=discount_real]','#order-form').forEach(el=>el.addEventListener('input',recalc));addLine();
 $('#order-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target);const items=$$('.order-line').map(row=>({product_id:$('[name=product_id]',row).value,quantity:Number($('[name=quantity]',row).value)}));const submit=$('[type=submit]','#order-form');submit.disabled=true;
  try{await api('orders','POST',{contact_id:fd.get('contact_id')||null,segment:fd.get('segment'),origin:fd.get('origin'),items,shipping_cents:moneyCents(fd.get('shipping_real')),discount_cents:moneyCents(fd.get('discount_real')),notes:fd.get('notes')});closeModal();toast('Novo pedido registrado.');await orders();pollAlerts(true)}catch(err){toast(err.message,'error');submit.disabled=false}
 });
}
async function orderDetail(id){const d=await api('orders/'+id);const o=d.order;modal('Pedido '+o.order_number,`<div class="detail-meta"><div><span>CLIENTE</span><strong>${esc(o.contact_name||'Não identificado')}</strong></div><div><span>PERFIL</span><strong>${esc(o.segment)}</strong></div><div><span>SITUAÇÃO</span><strong>${esc(o.status)}</strong></div><div><span>PAGAMENTO</span><strong>${esc(o.payment_status)}</strong></div></div>${rows(['ITEM','QTD','UNITÁRIO','SUBTOTAL'],d.items.map(x=>`<tr><td>${esc(x.name)}<small class="cell-secondary">${esc(x.sku)}</small></td><td>${x.quantity}</td><td>${money(x.unit_price_cents)}</td><td>${money(x.line_total_cents)}</td></tr>`))}<div class="detail-total"><span>Total do pedido</span><strong>${money(o.total_cents)}</strong></div><div class="detail-actions">${({novo:'confirmado',confirmado:'separando',separando:'enviado',enviado:'concluido'})[o.status]?`<button class="btn primary" data-action="order-status" data-id="${o.id}" data-value="${({novo:'confirmado',confirmado:'separando',separando:'enviado',enviado:'concluido'})[o.status]}">${{novo:'Confirmar pedido e baixar estoque',confirmado:'Iniciar separação',separando:'Marcar como enviado',enviado:'Marcar como concluído'}[o.status]}</button>`:''}${['novo','confirmado','separando'].includes(o.status)?`<button class="btn ghost danger" data-action="order-status" data-id="${o.id}" data-value="cancelado">Cancelar pedido</button>`:''}${isAdmin()&&o.status!=='cancelado'&&o.payment_status==='pendente'&&o.status!=='novo'?`<button class="btn ghost" data-action="order-payment" data-id="${o.id}" data-value="pago">Marcar pagamento recebido</button>`:''}${isAdmin()&&o.payment_status==='pago'?`<button class="btn ghost danger" data-action="order-payment" data-id="${o.id}" data-value="estornado">Registrar estorno realizado</button>`:''}</div><p class="form-hint">${esc(o.notes||'Nenhuma observação adicional.')}</p>`)}
function playSound(){if(!state.sound)return;try{const c=state.audio;if(!c||c.state==='suspended')return;const t=c.currentTime;for(const [i,h] of [740,988,1244].entries()){const osc=c.createOscillator(),gain=c.createGain();osc.type='sine';osc.frequency.value=h;gain.gain.setValueAtTime(.0001,t+i*.12);gain.gain.exponentialRampToValueAtTime(.09,t+i*.12+.012);gain.gain.exponentialRampToValueAtTime(.0001,t+i*.12+.23);osc.connect(gain);gain.connect(c.destination);osc.start(t+i*.12);osc.stop(t+i*.12+.23)}}catch{}}
async function activateSound(){if(state.sound){state.sound=false;localStorage.setItem('crm_sound','0');toast('Alerta sonoro desativado.')}else{state.sound=true;localStorage.setItem('crm_sound','1');try{state.audio=new (window.AudioContext||window.webkitAudioContext)();await state.audio.resume();playSound()}catch{toast('Seu navegador não habilitou o áudio.','error')}toast('Alertas sonoros ativados.')}$('#sound-toggle')?.classList.toggle('is-active',state.sound);if($('#sound-toggle'))$('#sound-toggle').innerHTML=`<span>${state.sound?'◖))':'◖)'}</span><span>${state.sound?'Alertas sonoros ativos':'Ativar alertas sonoros'}</span>`}
async function pollAlerts(silent=false){if(!state.user)return;try{const d=await api('alerts'),fresh=d.items.filter(x=>!state.alertIds.has(x.id));if(state.alertsReady&&fresh.length){const newest=fresh.find(x=>!x.read_at);if(newest){playSound();if(!silent)toast(newest.title);if(typeof Notification!=='undefined'&&Notification.permission==='granted'&&document.visibilityState==='hidden')new Notification(newest.title,{body:newest.description,icon:'/icon.svg'})}}state.alertIds=new Set(d.items.map(x=>x.id));state.alertsReady=true;state.data.alerts=d.items;const unread=d.items.filter(x=>!x.read_at).length;if($('#alerts-count')){$('#alerts-count').hidden=!unread;$('#alerts-count').textContent=unread>99?'99+':String(unread)}const side=$('#side-new-orders');if(side){side.textContent=unread||'';side.hidden=!unread}if($('#alerts-drawer')&&!$('#alerts-drawer').hidden)renderAlerts()}catch{/* Offline and paused tabs should not flood toasts. */}}
function toggleAlerts(){const drawer=$('#alerts-drawer');drawer.hidden=!drawer.hidden;if(!drawer.hidden)renderAlerts()}
function renderAlerts(){const arr=state.data.alerts||[],drawer=$('#alerts-drawer');drawer.innerHTML=`<div class="alerts-head"><div><span class="eyebrow">ACOMPANHAMENTO EM TEMPO REAL</span><h3>Notificações</h3></div><button class="modal-close" data-action="alerts-close" aria-label="Fechar alertas">×</button></div>${arr.length?`<div class="alerts-list">${arr.map(x=>`<div class="alert-item ${!x.read_at?'is-unread':''}"><span class="alert-dot ${x.kind}"></span><div><strong>${esc(x.title)}</strong><p>${esc(x.description)}</p><small>${esc(x.created_at)}</small></div></div>`).join('')}</div><button class="btn ghost full" data-action="alerts-read">Marcar todas como lidas</button>`:empty('Nenhuma notificação','Os pedidos e alertas de estoque aparecem aqui.')}`}
async function executeAction(action,id,value){switch(action){
 case'logout':await api('auth/logout','POST',{});state.user=null;return renderLogin();
 case'modal-close':return closeModal();case'alerts-close':return $('#alerts-drawer').hidden=true;
 case'alerts-read':await api('alerts/read-all','PATCH',{});await pollAlerts();return renderAlerts();
 case'contacts-import':return importCSV('contacts');case'products-import':return importCSV('products');case'contact-new':return openContact();case'contact-edit':return openContact(id);
 case'product-new':return openProduct();case'product-edit':return openProduct(id);case'stock-adjust':return adjustStock(id);case'inventory-history':return inventoryHistory();
 case'order-new':return openOrder();case'order-detail':return orderDetail(id);
 case'order-status':{
  if(!confirm(value==='confirmado'?'Confirmar pedido? O estoque será baixado.':value==='cancelado'?'Cancelar pedido? Se ele ainda não foi enviado, o estoque será restaurado.':'Atualizar situação do pedido?'))return;
  await api('orders/'+id+'/status','PATCH',{status:value});closeModal();toast('Situação do pedido atualizada.');await orders();await pollAlerts(true);return;}
 case'order-payment':if(!confirm(value==='estornado'?'Confirme APENAS se o valor já foi devolvido ao cliente. O CRM apenas registra o estorno, não transfere dinheiro.':'Confirmar recebimento deste pagamento?'))return;await api('orders/'+id+'/payment','PATCH',{payment_status:value});closeModal();toast('Pagamento atualizado.');return orders();
 case'deal-new':return openDeal();case'deal-edit':return openDeal(id);
 case'task-new':return openTask();case'task-edit':return openTask(id);
 case'task-toggle':{const old=state.data.tasks.items.find(x=>x.id===id);await api('tasks/'+id,'PATCH',{completed:old.completed?0:1});return tasks()}
 case'finance-new':return openFinance();case'finance-pay':if(!confirm('Confirmar que o valor foi pago/recebido?'))return;await api('finance/'+id,'PATCH',{status:'pago'});return finance();
 case'supplier-new':return openSupplier();case'user-new':return openUser();case'password-change':return changePassword();
 case'sound-toggle':return activateSound();case'install':return promptInstall();case'finance-export':return exportFinancialCSV();
 }}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){go(nav.dataset.nav);return}const el=e.target.closest('[data-action]');if(!el)return;executeAction(el.dataset.action,el.dataset.id,el.dataset.value).catch(err=>toast(err.message,'error'))});
async function boot(){try{const x=await api('auth/me');state.user=x.user;renderShell()}catch{try{const setup=await api('setup/status');if(setup.needs_setup)renderSetup();else renderLogin()}catch{renderLogin()}}if('serviceWorker'in navigator){navigator.serviceWorker.register('/sw.js').catch(()=>{})}}
setupExperience(toast);
boot();

/* Native notifications are optional: the PWA continues to work without push. */
function urlB64ToUint8Array(base64){const str=atob(base64.replace(/-/g,'+').replace(/_/g,'/')+'='.repeat((4-base64.length%4)%4));return Uint8Array.from(str,c=>c.charCodeAt(0))}
async function enableMobileNotifications(){
 if(!('Notification' in window)||!('serviceWorker' in navigator)||!('PushManager' in window))return toast('Este navegador não oferece notificações push.','error');
 const keys=await api('push/public-key');if(!keys.configured)return toast('Configure VAPID_PUBLIC_KEY, VAPID_PRIVATE_KEY e VAPID_SUBJECT no Worker.','error');
 const permission=await Notification.requestPermission();if(permission!=='granted')return toast('Permissão de notificações não concedida.','error');
 const registration=await navigator.serviceWorker.ready;
 const subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:urlB64ToUint8Array(keys.public_key)});
 await api('push/subscribe','POST',subscription.toJSON());await api('push/test','POST',{});toast('Notificações do celular habilitadas.');
}
const originalAction=executeAction;
executeAction=async function(action,id,value){if(action==='enable-push')return enableMobileNotifications();return originalAction(action,id,value)};


/** RFC4180-like parser: supports UTF-8 BOM, quotes, semicolons, commas and CRLF. */
function parseCSV(text){
 text=String(text).replace(/^\uFEFF/,'');const first=text.split(/\r?\n/)[0]||'';
 const sep=(first.match(/;/g)||[]).length>=(first.match(/,/g)||[]).length?';':',';
 const result=[];let row=[],cell='',quoted=false;
 for(let i=0;i<text.length;i++){
  const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}
  else if(!quoted&&c===sep){row.push(cell);cell=''}
  else if(!quoted&&(c==='\n'||c==='\r')){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))result.push(row);row=[];cell=''}
  else cell+=c;
 }
 row.push(cell);if(row.some(x=>x.trim()))result.push(row);
 const headers=result.shift()?.map(x=>x.trim().toLowerCase())||[];
 return result.map(row=>Object.fromEntries(headers.map((header,i)=>[header,row[i]?.trim()||''])));
}
async function importCSV(kind){
 const chooser=document.createElement('input');chooser.type='file';chooser.accept='.csv,text/csv';chooser.hidden=true;document.body.append(chooser);
 chooser.addEventListener('change',async()=>{
  const file=chooser.files?.[0];chooser.remove();if(!file)return;
  try{
   const records=parseCSV(await file.text());if(!records.length)throw new Error('O CSV não contém linhas para importar.');
   if(records.length>4000)throw new Error('Limite de 4.000 linhas por arquivo.');
   let items;
   if(kind==='contacts'){
    items=records.map(r=>({phone:r.telefone||r.phone||'',name:r.nome||r.name||r.telefone||r.phone||'',email:r.email||'',segment:r.segmento||r.segment||'varejo'}));
   }else{
    items=records.map(r=>({sku:r.sku||'',name:r.nome||r.name||'',category:r.categoria||r.category||'geral',retail_cents:moneyCents(r.varejo_reais||r.varejo||'0'),wholesale_cents:moneyCents(r.atacado_reais||r.atacado||'0'),cost_cents:moneyCents(r.custo_reais||r.custo||'0'),quantity:Number(r.estoque||0),min_quantity:Number(r.minimo||5)}));
   }
   if(!confirm(`Importar ${items.length} registro(s) do arquivo? Registros com SKU ou telefone já existentes serão ignorados.`))return;
   let imported=0,skipped=0;for(let i=0;i<items.length;i+=200){const res=await api(kind+'/import','POST',{items:items.slice(i,i+200)});imported+=res.created;skipped+=res.skipped}
   toast(`Importação concluída: ${imported} novos, ${skipped} ignorados.`);await renderSection();
  }catch(err){toast(err.message,'error')}
 });chooser.click();
}
